// Static server for the mock build (dist-e2e) that sends the response headers of the MOCK variant
// of vercel.json (generated by scripts/gen-vercel-json.mjs, localhost API origin), so the
// Content-Security-Policy is really enforced by the browser during E2E. Localhost only.
import { createReadStream, existsSync, statSync } from 'node:fs'
import { createServer } from 'node:http'
import { extname, join, normalize, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { buildConfig } from '../scripts/gen-vercel-json.mjs'

const port = Number(process.env.E2E_PORT ?? 4173)
const root = resolve(fileURLToPath(new URL('../dist-e2e', import.meta.url)))
const cfg = buildConfig(`http://localhost:${port}`, { mock: true })
const all = cfg.headers.find((h) => h.source === '/(.*)').headers
const assets = cfg.headers.find((h) => h.source === '/assets/(.*)').headers

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.woff2': 'font/woff2',
  '.woff': 'font/woff',
  '.svg': 'image/svg+xml',
  '.json': 'application/json',
  '.ico': 'image/x-icon',
}

createServer((req, res) => {
  const path = decodeURIComponent(new URL(req.url, 'http://x').pathname)
  let file = normalize(join(root, path))
  if (!file.startsWith(root)) {
    res.writeHead(403).end()
    return
  }
  // vercel.json rewrite: any path that is not a file serves index.html
  if (!existsSync(file) || statSync(file).isDirectory()) file = join(root, 'index.html')
  const headers = { 'Content-Type': TYPES[extname(file)] ?? 'application/octet-stream' }
  for (const h of all) headers[h.key] = h.value
  if (path.startsWith('/assets/')) for (const h of assets) headers[h.key] = h.value
  headers['Cache-Control'] = 'no-store' // deterministic runs; overrides the immutable asset header
  res.writeHead(200, headers)
  createReadStream(file).pipe(res)
}).listen(port, '127.0.0.1', () => console.log(`e2e server on http://localhost:${port}`))
